$ErrorActionPreference='Stop'
$repo='F:/JericoEngine/JericoEngine';$base=Join-Path $repo 'build/n0-validation/local-packages/tiff-rev1-validation';$extract=Join-Path $base 'extracted'
$consumer='F:/JericoEngine/JericoEngine/build/n0-validation/local-packages/tiff-consumer-rev1';$cmake='C:/Program Files/CMake/bin/cmake.exe';$ctest='C:/Program Files/CMake/bin/ctest.exe'
function Invoke-Captured {
 param([string]$Label,[string]$Executable,[string[]]$ArgumentVector,[string]$WorkingDirectory)
 $argvPath=Join-Path $base "$Label-argv.json";$outPath=Join-Path $base "$Label.stdout.log";$errPath=Join-Path $base "$Label.stderr.log";$resPath=Join-Path $base "$Label-result.json"
 [IO.File]::WriteAllText($argvPath,(@{executable=$Executable;workingDirectory=$WorkingDirectory;arguments=$ArgumentVector}|ConvertTo-Json -Depth 4),[Text.UTF8Encoding]::new($false))
 $psi=[Diagnostics.ProcessStartInfo]::new();$psi.FileName=$Executable;$psi.WorkingDirectory=$WorkingDirectory;$psi.UseShellExecute=$false;$psi.CreateNoWindow=$true;$psi.RedirectStandardOutput=$true;$psi.RedirectStandardError=$true;foreach($arg in $ArgumentVector){[void]$psi.ArgumentList.Add($arg)}
 $proc=[Diagnostics.Process]::new();$proc.StartInfo=$psi;$sw=[Diagnostics.Stopwatch]::StartNew();if(-not $proc.Start()){throw "Failed to start $Label"};$ot=$proc.StandardOutput.ReadToEndAsync();$et=$proc.StandardError.ReadToEndAsync();$proc.WaitForExit();$exit=$proc.ExitCode;$sw.Stop();$out=$ot.GetAwaiter().GetResult();$err=$et.GetAwaiter().GetResult()
 [IO.File]::WriteAllText($outPath,$out,[Text.UTF8Encoding]::new($false));[IO.File]::WriteAllText($errPath,$err,[Text.UTF8Encoding]::new($false));$r=[ordered]@{label=$Label;exitCode=$exit;elapsedSeconds=[Math]::Round($sw.Elapsed.TotalSeconds,3);stdoutBytes=[Text.Encoding]::UTF8.GetByteCount($out);stderrBytes=[Text.Encoding]::UTF8.GetByteCount($err)};[IO.File]::WriteAllText($resPath,($r|ConvertTo-Json -Depth 4),[Text.UTF8Encoding]::new($false));return [pscustomobject]$r
}
$archive='F:/JericoEngine/JericoEngine/build/n0-validation/local-packages/tiff-rev1/packages/tiff-4.2.0.15-je-rev1-windows.tar.xz';$audit=Get-Content -Raw (Join-Path $base 'tiff-package-audit.json')|ConvertFrom-Json
if((Get-FileHash $archive -Algorithm SHA256).Hash.ToLowerInvariant() -ne [string]$audit.archiveSHA256){throw 'Package archive changed after audit'}
if(-not (Test-Path (Join-Path $extract 'FindTIFF.cmake')) -or -not (Test-Path (Join-Path $extract 'SHA256SUMS'))){throw 'Fresh archive extraction is incomplete'}
$freezePath=Join-Path $repo 'build/n0-validation/local-packages/tiff-audit/source-freeze-tiff-candidate-v2.json';$freeze=Get-Content -Raw $freezePath|ConvertFrom-Json;$before=@{};foreach($entry in $freeze.entries){$before[[string]$entry.path]=(Get-FileHash $entry.path -Algorithm SHA256).Hash.ToUpperInvariant()}
$argsFile=Join-Path $repo 'build/n0-validation/local-packages/tiff-audit/validation-arguments.json';$manifest=Get-Content -Raw $argsFile|ConvertFrom-Json;$vector=[string[]]$manifest.consumerConfigure.argv;$vector[10]="-DJE_TIFF_PACKAGE_ROOT:PATH=$extract"
if($vector.Count -ne 12 -or $vector[0] -ne '-S' -or $vector[2] -ne '-B' -or $vector[3].Replace('\','/') -ne $consumer.Replace('\','/')){throw 'Consumer configure argv failed exact path/count/mode guard'}
if(Test-Path $consumer){throw 'Consumer path exists; refusing overwrite'}
[IO.File]::WriteAllText((Join-Path $base 'tiff-consumer-inputs-before.json'),(@{freezeSHA256=(Get-FileHash $freezePath -Algorithm SHA256).Hash;archiveSHA256=$audit.archiveSHA256;inputCount=$before.Count;sourceHashes=$before}|ConvertTo-Json -Depth 5),[Text.UTF8Encoding]::new($false))
$conf=Invoke-Captured 'tiff-consumer-configure' $cmake $vector $base;if($conf.exitCode -ne 0){throw "TIFF consumer configure failed $($conf.exitCode)"}
$build=Invoke-Captured 'tiff-consumer-build-release' $cmake ([string[]]@('--build',$consumer,'--config','Release','--target','JE_TiffConsumer')) $base;if($build.exitCode -ne 0){throw "TIFF consumer build failed $($build.exitCode)"}
$test=Invoke-Captured 'tiff-consumer-ctest-release' $ctest ([string[]]@('--test-dir',$consumer,'-C','Release','--output-on-failure','--verbose')) $base;$last=Join-Path $consumer 'Testing/Temporary/LastTest.log';if(Test-Path $last){Copy-Item $last (Join-Path $base 'LastTest-Release.log')};if($test.exitCode -ne 0){throw "TIFF consumer CTest failed $($test.exitCode)"}
$after=@();foreach($entry in $freeze.entries){$p=[string]$entry.path;$h=(Get-FileHash $p -Algorithm SHA256).Hash.ToUpperInvariant();$after += [ordered]@{path=$p;sha256=$h;matchesFreeze=($h -eq [string]$entry.sha256);matchesBefore=($h -eq $before[$p])}}
[IO.File]::WriteAllText((Join-Path $base 'tiff-consumer-inputs-after.json'),(@{inputCount=$after.Count;allMatch=(@($after|Where-Object{!$_.matchesFreeze}).Count -eq 0);inputs=$after}|ConvertTo-Json -Depth 5),[Text.UTF8Encoding]::new($false))
$summary=[ordered]@{archiveSHA256=$audit.archiveSHA256;archiveMembers=$audit.memberCount;payloads=$audit.manifestEntryCount;links=$audit.linkEntryCount;configureExit=$conf.exitCode;buildExit=$build.exitCode;ctestExit=$test.exitCode;ctestSummary=(Select-String -Path (Join-Path $base 'tiff-consumer-ctest-release.stdout.log') -Pattern '100% tests passed'|ForEach-Object{$_.Line});freezeInputs=$after.Count;freezeMatches=(@($after|Where-Object{!$_.matchesFreeze}).Count -eq 0)}
[IO.File]::WriteAllText((Join-Path $base 'tiff-consumer-summary.json'),($summary|ConvertTo-Json -Depth 6),[Text.UTF8Encoding]::new($false));Write-Output ($summary|ConvertTo-Json -Compress -Depth 5)
